form.example:
druids.form("Pin this model:", { title: "Pin", fields: [
  { name: "num_ctx", label: "Context length", type: "number", min: 1, hint: "Tokens." },
  { name: "kind", label: "Model type", type: "select", options: [{ value: "", label: "Auto-detect" }] },
], confirmLabel: "Pin" }).then(values => { if (values) pin(values.num_ctx, values.kind); });

anchor.example:
menu.setAttribute("popover", "manual");
const pin = druids.anchor(menu, input, { placement: "bottom-start", matchWidth: true });
/* after the menu's content changed */ pin.update();
/* on close */ pin.release();
